export function exportRun(run){return {schemaVersion:'1.0',kind:'VEIL_REPLAY_BUNDLE',softwareBuildId:'symbio-veil/1.0.0',modelVersion:MODEL_VERSION,scenarioHash:hash(run.initialOptions),scenario:run.scenario,seed:run.seed,policyId:run.policyId,policyWeights:weights,numericalConfig:run.numericalConfig,provenance:'P2 SYNTHETIC REFERENCE',limitations:LIMITATIONS,initialOptions:run.initialOptions,initialStates:run.initialState?.spacecraft,finalState:snapshot(run),events:run.events,faults:run.faults,ledger:run.ledger,decisions:run.decisions,contracts:run.contracts,metrics:run.metrics,checkpoints:run.checkpoints,replayState:copy({...run,initialState:undefined}),logHash:hash(run.events),hash:hash({time:run.time,spacecraft:run.spacecraft,queue:run.queue,rng:run.rng})};}
export function importRun(bundle){if(bundle.schemaVersion!=='1.0'||bundle.kind!=='VEIL_REPLAY_BUNDLE'||!bundle.replayState)fail('VERSION_MISMATCH','Expected VEIL 1.x replay bundle.');const source=copy(bundle.replayState);if(!Array.isArray(source.spacecraft)||!Array.isArray(source.queue)||!Number.isFinite(source.time))fail('INVALID_PARAMETER','Replay has invalid world data.');if(bundle.hash!==hash({time:source.time,spacecraft:source.spacecraft,queue:source.queue,rng:source.rng}))fail('CHECKSUM_MISMATCH','Replay checksum failed.');source.playing=false;source.runId=randomUUID();source.lastCommandRevision=source.revision;return source;}
export function experiment(options={}){const scenarioId=options.scenarioId||options.scenario_id||'E1',seed=Number(options.seed??20261029),duration=numeric(options.durationS??options.duration_s??1800,'Experiment duration',1,86400),rows=[];const selected=options.policies||['B0','B1','B2','B3'];if(!Array.isArray(selected)||!selected.length||selected.some(p=>!['B0','B1','B2','B3'].includes(p)))fail('INVALID_PARAMETER','Choose at least one valid comparison policy.');for(const policyId of [...new Set(selected)].sort()){const run=makeRun({scenarioId,seed,policyId});advance(run,duration);rows.push({policyId,label:({B0:'Independent',B1:'Reactive',B2:'Docking first',B3:'VEIL weighted'})[policyId],scenarioId,seed,scenarioHash:hash({scenarioId,seed}),durationS:duration,metrics:copy(run.metrics),outcome:run.spacecraft[0].mission.status,donorEnergyWh:run.spacecraft[1].energyWh,events:run.events,decisions:run.decisions,modelVersion:MODEL_VERSION,limitations:LIMITATIONS});}return {id:randomUUID(),schemaVersion:'1.0',scenarioId,seed,durationS:duration,provenance:'P2 SYNTHETIC',policies:rows,results:rows,sharedExogenousDisturbances:true,assumptions:'Identical initial states, scheduled fault and initial RNG streams. Policy-dependent resource states may induce different protection outcomes. No confidence interval claimed from one seed.'};}
